SourceCode.Declaration:
/// <summary>
/// Job class to populate NVOrderTypeTable with 62 predefined order types.
/// This is a one-time initialization job that should be run during system setup.
/// </summary>
/// <remarks>
/// Prerequisites: NVOrderTypeGroup table must be populated first (run NVFillOrderTypeGroups).
/// Includes duplicate prevention - the job will not insert data if 62+ types already exist.
///
/// Order types are organized into 12 groups:
/// - GROUP 1: Recruitment (4 types)
/// - GROUP 2: Position and salary change (7 types)
/// - GROUP 3: Termination (11 types)
/// - GROUP 4: Average salary protection (6 types)
/// - GROUP 5: Maternity leave (2 types)
/// - GROUP 6: Business trip (5 types)
/// - GROUP 7: Paid leave (1 type)
/// - GROUP 8: Social leave (2 types)
/// - GROUP 9: Education leave (1 type)
/// - GROUP 10: Unpaid leave (1 type)
/// - GROUP 11: Overtime (1 type)
/// - GROUP 12: Others (21 types)
/// </remarks>
class NVFillOrderTypes
{
}

Method.Source:
/// <summary>
/// Main entry point for the job.
/// Populates NVOrderTypeTable with 62 order types linked to their respective groups.
/// </summary>
/// <param name="_args">Job arguments (not used)</param>
public static void main(Args _args)
{
    NVOrderTypeTable orderTypeTable;
    NVOrderTypeGroup orderTypeGroup;
    int insertCount = 0;
    int existingCount = 0;

    // Check if data already exists to prevent duplicates
    existingCount = (select count(RecId) from NVOrderTypeTable).RecId;

    if (existingCount >= 62)
    {
        warning(strFmt("Data already exists! Found %1 types in table.", existingCount));
        warning("Job execution cancelled to prevent duplicates.");
        return;
    }

    ttsbegin;

    // ========================================
    // GROUP 1: RECRUITMENT (4 types)
    // ========================================
    orderTypeGroup = NVOrderTypeGroup::findByGroupId(1);

    if (orderTypeGroup.RecId)
    {
        // Type 1: Employment with allowance
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::EmpWithAllow).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::EmpWithAllow;
            orderTypeTable.TypeName = "İşə qəbul əmri əlavəli";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 1;
            orderTypeTable.Description = "Employment with allowance";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 2: Employment with allowance (harmful)
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::EmpWithAllowHarmful).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::EmpWithAllowHarmful;
            orderTypeTable.TypeName = "İşə qəbul əmri əlavəli+zərərli";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 2;
            orderTypeTable.Description = "Employment with allowance (harmful)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 3: Employment without allowance
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::EmpWithoutAllow).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::EmpWithoutAllow;
            orderTypeTable.TypeName = "İşə qəbul əmri əlavəsiz";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 3;
            orderTypeTable.Description = "Employment without allowance";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 4: Employment without allowance (harmful)
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::EmpWithoutAllowHarmful).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::EmpWithoutAllowHarmful;
            orderTypeTable.TypeName = "İşə qəbul əmri əlavəsiz+zərərli";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 4;
            orderTypeTable.Description = "Employment without allowance (harmful)";
            orderTypeTable.insert();
            insertCount++;
        }
    }

    // ========================================
    // GROUP 2: POSITION AND SALARY CHANGE (7 types)
    // ========================================
    orderTypeGroup = NVOrderTypeGroup::findByGroupId(2);

    if (orderTypeGroup.RecId)
    {
        // Type 5: Position change order
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::PosChange).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::PosChange;
            orderTypeTable.TypeName = "Vəzifə dəyişikliyi əmri";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 1;
            orderTypeTable.Description = "Position change order";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 6
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::PosChangeFlight).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::PosChangeFlight;
            orderTypeTable.TypeName = "Vəzifə dəyişikliyi SAŞ (Uçuş və kabinə heyəti)";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 2;
            orderTypeTable.Description = "Position change (Flight and cabin crew)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 7
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::SalaryAllowChange).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::SalaryAllowChange;
            orderTypeTable.TypeName = "Əmək haqqının əlavəsinin dəyişikliyi əmri";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 3;
            orderTypeTable.Description = "Salary allowance change order";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 8
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::SalaryChange).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::SalaryChange;
            orderTypeTable.TypeName = "Əmək haqqının dəyişikliyi əmri";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 4;
            orderTypeTable.Description = "Salary change order";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 9
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::SalaryChangePilot).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::SalaryChangePilot;
            orderTypeTable.TypeName = "Əmək haqqı dəyişikliyi SAŞ (pilot)";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 5;
            orderTypeTable.Description = "Salary change (Pilot)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 10
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::SalaryChangePilotLong).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::SalaryChangePilotLong;
            orderTypeTable.TypeName = "Əmək haqqı dəyişikliyi SAŞ (pilot) uzunmüddətli xidmət";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 6;
            orderTypeTable.Description = "Salary change (Pilot long-term service)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 11
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::SalaryChangeP6C3).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::SalaryChangeP6C3;
            orderTypeTable.TypeName = "Əmək haqqı dəyişikliyi (SAŞ) P6 və C3 kateqoriyası";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 7;
            orderTypeTable.Description = "Salary change (P6 and C3 category)";
            orderTypeTable.insert();
            insertCount++;
        }
    }

    // ========================================
    // GROUP 3: TERMINATION (11 types)
    // ========================================
    orderTypeGroup = NVOrderTypeGroup::findByGroupId(3);

    if (orderTypeGroup.RecId)
    {
        // Type 12
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term68_2a).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term68_2a;
            orderTypeTable.TypeName = "Xitam 68.2a tərəflərdən birinin təşəbbüsü";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 1;
            orderTypeTable.Description = "Termination 68.2a (Initiative of one party)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 13
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term68_2b).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term68_2b;
            orderTypeTable.TypeName = "Xitam 68.2b əmək müqaviləsinin müddətinin qurtarması";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 2;
            orderTypeTable.Description = "Termination 68.2b (Contract expiration)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 14
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term68_2e).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term68_2e;
