            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 4;
            orderTypeTable.Description = "Termination 69.3 (Other employer contract)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 16
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term70_b).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term70_b;
            orderTypeTable.TypeName = "Xitam 70.b işçilərin sayı və ya ştatları ixtisar edildikdə";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 5;
            orderTypeTable.Description = "Termination 70.b (Staff reduction)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 17
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term70_c).RecId)
