            orderTypeTable.TypeName = "Xitam 70.ç işçi özünün əmək funksiyasını və ya əmək müqaviləsi üzrə öhdəliklərini yerinə yetirmədikdə";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 6;
            orderTypeTable.Description = "Termination 70.c (Non-performance)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 18
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term70_d).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term70_d;
            orderTypeTable.TypeName = "Xitam 70.d sınaq müddəti ərzində işçi özünü doğrultmadıqda";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 7;
            orderTypeTable.Description = "Termination 70.d (Probation period)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 19
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term74_1a).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term74_1a;
            orderTypeTable.TypeName = "Xitam 74.1a işçi hərbi və ya alternativ xidmətə çağırıldıqda";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 8;
            orderTypeTable.Description = "Termination 74.1a (Military service)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 20
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term74_1c).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term74_1c;
            orderTypeTable.TypeName = "Xitam 74.1c işçi əmək funksiyasını yerinə yetirə bilmədikdə";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 9;
            orderTypeTable.Description = "Termination 74.1c (Unable to perform)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 21
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term74_1ch).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term74_1ch;
            orderTypeTable.TypeName = "Xitam 74.1ç məhkəmənin hökmü qanuni qüvvəyə mindikdə";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 10;
            orderTypeTable.Description = "Termination 74.1ch (Court verdict)";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 22
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::Term74_1e).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::Term74_1e;
            orderTypeTable.TypeName = "Xitam 74.1e işçi vəfat etdikdə";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 11;
            orderTypeTable.Description = "Termination 74.1e (Death)";
            orderTypeTable.insert();
            insertCount++;
        }
    }

    // ========================================
    // GROUP 4: AVERAGE SALARY PROTECTION (6 types)
    // ========================================
    orderTypeGroup = NVOrderTypeGroup::findByGroupId(4);

    if (orderTypeGroup.RecId)
    {
        // Type 23
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::AvgSalMilitary).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::AvgSalMilitary;
            orderTypeTable.TypeName = "Hərbi Çağırış Haqqında əmri";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 1;
            orderTypeTable.Description = "Military service order";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 24
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::AvgSalSports).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::AvgSalSports;
            orderTypeTable.TypeName = "İdman yarışı barədə əmr";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 2;
            orderTypeTable.Description = "Sports competition order";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 25
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::AvgSalCourt).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::AvgSalCourt;
