            orderTypeTable.TypeName = "qan donuru ödənişli məzuniyyət əmri";
            orderTypeTable.GroupRecId = orderTypeGroup.RecId;
            orderTypeTable.IsActive = NoYes::Yes;
            orderTypeTable.SortOrder = 4;
            orderTypeTable.Description = "Blood donor paid leave order";
            orderTypeTable.insert();
            insertCount++;
        }

        // Type 27
        if (!NVOrderTypeTable::findByOrderType(NVOrderType::AvgSalElection).RecId)
        {
            orderTypeTable.clear();
            orderTypeTable.OrderType = NVOrderType::AvgSalElection;
            orderTypeTable.TypeName = "Seçki ilə ödənişli məzuniyyət əmri";
